package main

import (
	"fmt"
	"math"
	"sync"
)

// Place names for "Near": the neighbourhood a node is in (Seattle and
// Portland, from their cities' official boundaries), otherwise the closest
// town, from a built-in list (places_data.go, generated by
// scripts/places/gen-places.py) covering the western US and BC. Nothing is
// looked up online.

type place struct {
	name   string
	region string // state or province code
	lat    float64
	lon    float64
}

// hood is one neighbourhood boundary polygon. Rings hold flat lat, lon
// pairs: the outline first, then any holes.
type hood struct {
	name  string
	city  string
	rings [][]float64

	minLat, maxLat, minLon, maxLon float64
}

const (
	// Beyond this the node is described by its distance from the town.
	placeNearKm = 8.0
	// Beyond this the list has nothing useful to say.
	placeMaxKm = 150.0
	// A node this close outside a neighbourhood's edge counts as in it:
	// saved positions are often off by tens of metres, and a boundary that
	// is also the city limit would otherwise drop it to the nearest town.
	hoodEdgeSlackM = 150.0
)

var hoodBoundsOnce sync.Once

func hoodBounds() {
	for i := range hoodList {
		h := &hoodList[i]
		h.minLat, h.minLon = math.MaxFloat64, math.MaxFloat64
		h.maxLat, h.maxLon = -math.MaxFloat64, -math.MaxFloat64
		if len(h.rings) == 0 {
			continue
		}
		r := h.rings[0]
		for j := 0; j+1 < len(r); j += 2 {
			h.minLat = math.Min(h.minLat, r[j])
			h.maxLat = math.Max(h.maxLat, r[j])
			h.minLon = math.Min(h.minLon, r[j+1])
			h.maxLon = math.Max(h.maxLon, r[j+1])
		}
	}
}

// inRing is the even-odd test for a point in one ring of flat lat, lon pairs.
func inRing(r []float64, lat, lon float64) bool {
	in := false
	n := len(r) / 2
	for i, j := 0, n-1; i < n; j, i = i, i+1 {
		yi, xi := r[2*i], r[2*i+1]
		yj, xj := r[2*j], r[2*j+1]
		if (yi > lat) != (yj > lat) && lon < (xj-xi)*(lat-yi)/(yj-yi)+xi {
			in = !in
		}
	}
	return in
}

// hoodAt is the neighbourhood containing lat/lon, or nil.
func hoodAt(lat, lon float64) *hood {
	hoodBoundsOnce.Do(hoodBounds)
	for i := range hoodList {
		h := &hoodList[i]
		if lat < h.minLat || lat > h.maxLat || lon < h.minLon || lon > h.maxLon {
			continue
		}
		if !inRing(h.rings[0], lat, lon) {
			continue
		}
		inHole := false
		for _, hole := range h.rings[1:] {
			if inRing(hole, lat, lon) {
				inHole = true
				break
			}
		}
		if !inHole {
			return h
		}
	}
	return nil
}

// hoodNear is the neighbourhood whose outline passes within hoodEdgeSlackM
// of lat/lon (the closest such), or nil.
func hoodNear(lat, lon float64) *hood {
	hoodBoundsOnce.Do(hoodBounds)
	const mPerDegLat = 111320.0
	mPerDegLon := mPerDegLat * math.Cos(lat*math.Pi/180)
	padLat := hoodEdgeSlackM / mPerDegLat
	padLon := hoodEdgeSlackM / mPerDegLon
	var best *hood
	bestM := hoodEdgeSlackM
	for i := range hoodList {
		h := &hoodList[i]
		if lat < h.minLat-padLat || lat > h.maxLat+padLat || lon < h.minLon-padLon || lon > h.maxLon+padLon {
			continue
		}
		r := h.rings[0]
		n := len(r) / 2
		for a, b := n-1, 0; b < n; a, b = b, b+1 {
			// Distance to the segment, on a local flat projection in metres.
			ax, ay := (r[2*a+1]-lon)*mPerDegLon, (r[2*a]-lat)*mPerDegLat
			bx, by := (r[2*b+1]-lon)*mPerDegLon, (r[2*b]-lat)*mPerDegLat
			dx, dy := bx-ax, by-ay
			t := 0.0
			if l2 := dx*dx + dy*dy; l2 > 0 {
				t = math.Max(0, math.Min(1, -(ax*dx+ay*dy)/l2))
			}
			if d := math.Hypot(ax+t*dx, ay+t*dy); d <= bestM {
				best, bestM = h, d
			}
		}
	}
	return best
}

// nearPlace names where lat/lon is: the Seattle or Portland neighbourhood
// it's in, or just outside the edge of ("Denny Triangle, Seattle"), else the
// closest town ("Woodinville, WA"), or "12 km from Sequim, WA" when the
// closest town is more than placeNearKm away. Empty without a position or
// nothing within placeMaxKm.
func nearPlace(lat, lon float64) string {
	if (lat == 0 && lon == 0) || math.IsNaN(lat) || math.IsNaN(lon) {
		return ""
	}
	h := hoodAt(lat, lon)
	if h == nil {
		h = hoodNear(lat, lon)
	}
	if h != nil {
		return h.name + ", " + h.city
	}
	best, bestKm := -1, math.MaxFloat64
	for i := range placeList {
		p := &placeList[i]
		// Cheap box test before the haversine: a degree of latitude is
		// ~111 km, of longitude less, so this never drops a closer place.
		if math.Abs(p.lat-lat) > bestKm/111 {
			continue
		}
		if d := haversineKm(lat, lon, p.lat, p.lon); d < bestKm {
			best, bestKm = i, d
		}
	}
	if best < 0 || bestKm > placeMaxKm {
		return ""
	}
	p := placeList[best]
	label := p.name + ", " + p.region
	if bestKm > placeNearKm {
		return fmt.Sprintf("%.0f km from %s", bestKm, label)
	}
	return label
}
